#!/bin/zsh
# Mac Q8_0 WebGen-LM continual Long Memory run.
# First completes 000019--000021, then continues only with the later portion
# of the 101-task manifest.  Tasks 000014--000018 are a separate earlier
# cohort and must not be generated by this run.  Existing completed events are
# skipped; no output is overwritten.
set -euo pipefail

script_dir="${0:A:h}"
project_root="${script_dir:h}"
output="${WEBGEN_RUN_OUTPUT:-$project_root/outputs/experiment/longmem_mac_q8_19_21_then_remaining_r1}"
database="${WEBGEN_RUN_DATABASE:-$output/memory.db}"
bolt_port="${WEBGEN_BOLT_PORT:-5186}"
bolt_url="${WEBGEN_BOLT_URL:-http://127.0.0.1:${bolt_port}/}"

mkdir -p "$output"
cd "$project_root"

# Preflight uses small health calls only and fails before generation if any
# generator, evaluator, reflection, appearance, or embedding role is missing.
env/webvoyager/bin/python3.10 scripts/preflight_reflective_models.py |& tee -a "$output/preflight.log"

bolt_pid=""
if lsof -nP -iTCP:"$bolt_port" -sTCP:LISTEN >/dev/null 2>&1; then
  print "Reusing an existing Bolt listener on $bolt_port." | tee -a "$output/bolt.log"
else
  "$script_dir/start_bolt_provider.sh" --provider local --port "$bolt_port" >>"$output/bolt.log" 2>&1 &
  bolt_pid=$!
fi
cleanup() { [[ -n "$bolt_pid" ]] && kill -TERM "$bolt_pid" 2>/dev/null || true; }
trap cleanup EXIT INT TERM

for _ in {1..60}; do
  curl --fail --silent --show-error --max-time 5 "${bolt_url}api/health" >/dev/null && break
  sleep 1
done
curl --fail --silent --show-error --max-time 5 "${bolt_url}api/health" >/dev/null || {
  tail -80 "$output/bolt.log" >&2
  exit 1
}

# The Mac generator decodes at roughly 12--13.5 tok/s.  Permit 45 minutes for
# a long response rather than treating a healthy slow decode as a failure.
export WEBGEN_GENERATION_TIMEOUT_SECONDS="${WEBGEN_GENERATION_TIMEOUT_SECONDS:-2700}"
export WEBGEN_MAX_REPAIR_ATTEMPTS="${WEBGEN_MAX_REPAIR_ATTEMPTS:-1}"

run_tasks() {
  PYTHONUNBUFFERED=1 env/webvoyager/bin/python3.10 scripts/run_continual_memory.py \
    --modes continual \
    --post-task-reflection \
    --memory-representation case_only \
    --url "$bolt_url" \
    --generator-model "${WEBGEN_GENERATOR_API_MODEL:-WebGen-LM-7B}" \
    --output "$output" \
    --database "$database" \
    "$@" 2>&1 | while IFS= read -r line || [[ -n "$line" ]]; do
      printf '[%s] %s\n' "$(date '+%Y-%m-%dT%H:%M:%S%z')" "$line"
    done | tee -a "$output/runner.log"
}

# Explicit initial sequence requested by the user.
run_tasks --task-ids 000019,000020,000021

# Continue in manifest order, but deliberately exclude the earlier 000014--
# 000018 cohort as well as the initial 000019--000021 cohort.  Deriving the
# list from the manifest keeps this aligned with its 101 declared tasks.
later_task_ids="$(env/webvoyager/bin/python3.10 -c '
import json
from pathlib import Path
manifest = json.loads(Path("data/experiment_splits/continual_domain_blocks/manifest.json").read_text())
ids = [task_id for block in manifest["batches"] for task_id in block["task_ids"]
       if int(task_id) >= 22]
print(",".join(ids))
')"
[[ -n "$later_task_ids" ]] || { print "No later task IDs found in manifest." >&2; exit 1; }
run_tasks --task-ids "$later_task_ids"
